1	package cli
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"os"
13		"sort"
14		"strconv"
15		"strings"
16	
17		"github.com/spf13/cobra"
18	
19		"github.com/entireio/cli/cmd/entire/cli/api"
20		"github.com/entireio/cli/cmd/entire/cli/auth"
21		"github.com/entireio/cli/cmd/entire/cli/gitremote"
22		"github.com/entireio/cli/internal/coreapi"
23	)
24	
25	const apiMaxResponseBytes = 32 << 20 // 32 MiB cap on a printed response body.
26	
27	type apiFlags struct {
28		to           string
29		method       string
30		rawFields    []string
31		typedFields  []string
32		headers      []string
33		input        string
34		include      bool
35		insecureHTTP bool
36	}
37	
38	func newAPICmd() *cobra.Command {
39		f := &apiFlags{}
40		cmd := &cobra.Command{
41			Use:   "api <path>",
42			Short: "Make an authenticated request to an Entire API and print the response",
43			Long: "Make an authenticated HTTP request to an Entire API and print the JSON response.\n\n" +
44				"The CLI attaches the right bearer token and dials the right host for the\n" +
45				"chosen backend, so you don't have to plumb auth yourself:\n\n" +
46				"  --to core   the control plane (default): orgs, repos, mirrors, clusters, /me\n" +
47				"  --to cell   your home entire-api cell: /me/* activity, repo aggregates\n\n" +
48				"<path> is the full path on that host, e.g. /api/v1/clusters. These\n" +
49				"placeholders are filled from the current repo's origin remote:\n" +
50				"  {owner} {repo}   the GitHub owner / repo\n" +
51				"  {repo_id}        the repo's Entire ULID (from its mirror) — cells key on this\n\n" +
52				"The method is GET unless a field/body is given (then POST); override with -X.",
53			Example: "  entire api /api/v1/clusters\n" +
54				"  entire api --to cell /api/v1/me/activity\n" +
55				"  entire api --to cell \"/api/v1/me/recap?repo={repo_id}\"\n" +
56				"  entire api -X POST /api/v1/projects -f name=demo",
57			Args: cobra.ExactArgs(1),
58			RunE: func(cmd *cobra.Command, args []string) error {
59				return runAPI(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), args[0], f)
60			},
61		}
62		cmd.Flags().StringVar(&f.to, "to", "core", "which backend to call: core or cell")
63		cmd.Flags().StringVarP(&f.method, "method", "X", "", "HTTP method (default GET, or POST when a field/body is given)")
64		cmd.Flags().StringArrayVarP(&f.rawFields, "raw-field", "f", nil, "add a string parameter in key=value format (repeatable)")
65		cmd.Flags().StringArrayVarP(&f.typedFields, "field", "F", nil, "add a typed parameter in key=value format; true/false/null/numbers are converted (repeatable)")
66		cmd.Flags().StringArrayVarP(&f.headers, "header", "H", nil, "add a request header in key:value format (repeatable)")
67		cmd.Flags().StringVar(&f.input, "input", "", "file with the request body (\"-\" for stdin)")
68		cmd.Flags().BoolVarP(&f.include, "include", "i", false, "print the response status line and headers too")
69		addInsecureHTTPAuthFlag(cmd, &f.insecureHTTP)
70		return cmd
71	}
72	
73	func runAPI(ctx context.Context, w, errW io.Writer, rawPath string, f *apiFlags) error {
74		insecure := applyInsecureHTTPAuth(f.insecureHTTP)
75	
76		client, err := resolveAPIClient(ctx, f.to, insecure)
77		if err != nil {
78			return err
79		}
80	
81		path, err := expandAPIPlaceholders(ctx, rawPath)
82		if err != nil {
83			return err
84		}
85		if err := validateAPIPath(path); err != nil {
86			return err
87		}
88	
89		fields, err := buildAPIFields(f.rawFields, f.typedFields)
90		if err != nil {
91			return err
92		}
93	
94		req, err := buildAPIRequestBody(path, f, fields)
95		if err != nil {
96			return err
97		}
98	
99		headers, err := parseAPIHeaders(f.headers)
100		if err != nil {
101			return err
102		}
103	
104		resp, err := client.Request(ctx, req.method, req.path, headers, req.body)
105		if err != nil {
106			return fmt.Errorf("%s %s: %w", req.method, req.path, err)
107		}
108		defer func() { _ = resp.Body.Close() }()
109	
110		return writeAPIResponse(w, errW, resp, f.include)
111	}
112	
113	// resolveAPIClient builds an authenticated client for the chosen backend. Both
114	// return an *api.Client whose base URL is the backend origin, so <path> is the
115	// full path (e.g. /api/v1/…) against that host.
116	func resolveAPIClient(ctx context.Context, to string, insecure bool) (*api.Client, error) {
117		switch strings.ToLower(strings.TrimSpace(to)) {
118		case "", "core":
119			target, err := resolveAuthStatusTarget(ctx, auth.Contexts, auth.RefreshedLoginToken)
120			if err != nil {
121				return nil, err
122			}
123			if target.token == "" {
124				// Return a normal (non-silent) error so main.go prints the hint;
125				// a SilentError would exit non-zero with no explanation.
126				return nil, errors.New("not logged in: run 'entire login' to authenticate")
127			}
128			if !insecure && target.coreURL != "" {
129				if err := api.RequireSecureURL(target.coreURL); err != nil {
130					return nil, fmt.Errorf("control-plane URL check: %w", err)
131				}
132			}
133			return api.NewClientWithBaseURL(target.token, target.coreURL), nil
134		case "cell":
135			client, err := auth.NewEntireAPICellClient(ctx, insecure, nil)
136			if err != nil {
137				return nil, err //nolint:wrapcheck // NewEntireAPICellClient already returns contextual auth errors
138			}
139			return client, nil
140		default:
141			return nil, fmt.Errorf("unknown --to %q (use core or cell)", to)
142		}
143	}
144	
145	// validateAPIPath rejects anything that isn't origin-relative. The path is
146	// resolved against the backend origin via url.ResolveReference, which lets an
147	// absolute ("https://evil/…") or scheme-relative ("//evil/…") value replace the
148	// host — and the bearer transport would then send the Entire token there. So a
149	// path carrying its own scheme or host is refused before any request is made.
150	func validateAPIPath(path string) error {
151		u, err := url.Parse(path)
152		if err != nil {
153			return fmt.Errorf("invalid path %q: %w", path, err)
154		}
155		if u.Scheme != "" || u.Host != "" {
156			return fmt.Errorf("path must be origin-relative (e.g. /api/v1/…), not a cross-host or absolute URL: %q", path)
157		}
158		return nil
159	}
160	
161	// expandAPIPlaceholders fills {owner}/{repo}/{repo_id} from the current repo.
162	// Resolution is lazy: {owner}/{repo} need only the git remote; {repo_id} costs
163	// a control-plane mirror lookup, so it's only done when actually referenced.
164	func expandAPIPlaceholders(ctx context.Context, s string) (string, error) {
165		needOwnerRepo := strings.Contains(s, "{owner}") || strings.Contains(s, "{repo}")
166		needRepoID := strings.Contains(s, "{repo_id}")
167		if !needOwnerRepo && !needRepoID {
168			return s, nil
169		}
170	
171		// Resolve the origin remote once, even when both {owner}/{repo} and
172		// {repo_id} are present, and thread it into the mirror lookup.
173		forge, owner, repo, err := gitremote.ResolveRemoteRepo(ctx, "origin")
174		if err != nil {
175			return "", fmt.Errorf("resolve current repo from origin remote: %w", err)
176		}
177		if needOwnerRepo {
178			s = strings.ReplaceAll(s, "{owner}", owner)
179			s = strings.ReplaceAll(s, "{repo}", repo)
180		}
181		if needRepoID {
182			id, err := resolveCurrentRepoID(ctx, forge, owner, repo)
183			if err != nil {
184				return "", err
185			}
186			s = strings.ReplaceAll(s, "{repo_id}", id)
187		}
188		return s, nil
189	}
190	
191	// resolveCurrentRepoID resolves a repo's Entire ULID from its mirror (the mirror
192	// id, which entire-api uses as the repo_id), given its already-resolved origin
193	// coordinates. Picks the first active placement.
194	func resolveCurrentRepoID(ctx context.Context, forge, owner, repo string) (string, error) {
195		if f := strings.ToLower(strings.TrimSpace(forge)); f != "gh" && f != mirrorCloneProviderGitHub {
196			return "", fmt.Errorf("{repo_id} needs a GitHub repo; origin forge is %q", forge)
197		}
198		c, err := coreapi.New()
199		if err != nil {
200			return "", fmt.Errorf("resolve {repo_id} needs the control plane: %w", err)
201		}
202		mirrors, err := listMirrorsForRepo(ctx, c, mirrorCloneProviderGitHub, strings.ToLower(owner), strings.ToLower(repo))
203		if err != nil {
204			return "", fmt.Errorf("list mirrors for %s/%s: %w", owner, repo, err)
205		}
206		for i := range mirrors {
207			if !isActiveMirror(mirrors[i]) {
208				continue
209			}
210			if id := strings.TrimSpace(mirrors[i].MirrorId); id != "" {
211				return id, nil
212			}
213		}
214		return "", fmt.Errorf("no active mirror for %s/%s to resolve {repo_id}", owner, repo)
215	}
216	
217	// buildAPIFields merges -f (always string) and -F (type-inferred) into one map.
218	// Returns an empty (non-nil) map when no fields are given.
219	func buildAPIFields(rawFields, typedFields []string) (map[string]any, error) {
220		out := make(map[string]any, len(rawFields)+len(typedFields))
221		for _, kv := range rawFields {
222			k, v, ok := strings.Cut(kv, "=")
223			if !ok || k == "" {
224				return nil, fmt.Errorf("invalid -f %q (want key=value)", kv)
225			}
226			out[k] = v
227		}
228		for _, kv := range typedFields {
229			k, v, ok := strings.Cut(kv, "=")
230			if !ok || k == "" {
231				return nil, fmt.Errorf("invalid -F %q (want key=value)", kv)
232			}
233			out[k] = inferFieldValue(v)
234		}
235		return out, nil
236	}
237	
238	// inferFieldValue mirrors gh's -F conversion: true/false/null and numbers get
239	// their JSON type; everything else stays a string.
240	func inferFieldValue(v string) any {
241		switch v {
242		case "true":
243			return true
244		case "false":
245			return false
246		case "null":
247			return nil
248		}
249		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
250			return n
251		}
252		if fl, err := strconv.ParseFloat(v, 64); err == nil {
253			return fl
254		}
255		return v
256	}
257	
258	type apiRequest struct {
259		method string
260		path   string
261		body   io.Reader
262	}
263	
264	// buildAPIRequestBody resolves method + body from the flags: --input wins (raw
265	// body), else fields become a JSON body. The method defaults to GET, or POST
266	// when there's a body; an explicit -X wins. For a GET with fields, the fields
267	// go on the query string instead of a body.
268	func buildAPIRequestBody(path string, f *apiFlags, fields map[string]any) (apiRequest, error) {
269		method := strings.ToUpper(strings.TrimSpace(f.method))
270		if method == "" {
271			if f.input != "" || len(fields) > 0 {
272				method = http.MethodPost
273			} else {
274				method = http.MethodGet
275			}
276		}
277	
278		if f.input != "" {
279			if len(fields) > 0 {
280				return apiRequest{}, errors.New("use either --input or -f/-F, not both")
281			}
282			raw, err := readAPIInput(f.input)
283			if err != nil {
284				return apiRequest{}, err
285			}
286			return apiRequest{method: method, path: path, body: bytes.NewReader(raw)}, nil
287		}
288	
289		if len(fields) == 0 {
290			return apiRequest{method: method, path: path, body: nil}, nil
291		}
292	
293		if method == http.MethodGet {
294			q, err := fieldsToQuery(fields)
295			if err != nil {
296				return apiRequest{}, err
297			}
298			return apiRequest{method: method, path: appendQuery(path, q), body: nil}, nil
299		}
300	
301		data, err := json.Marshal(fields)
302		if err != nil {
303			return apiRequest{}, fmt.Errorf("encode fields: %w", err)
304		}
305		return apiRequest{method: method, path: path, body: bytes.NewReader(data)}, nil
306	}
307	
308	// fieldsToQuery stringifies fields for a GET query string. Non-string scalars
309	// are rendered with their JSON form (e.g. true, 42) so -F round-trips sensibly.
310	func fieldsToQuery(fields map[string]any) (url.Values, error) {
311		q := make(url.Values, len(fields))
312		for k, v := range fields {
313			switch val := v.(type) {
314			case string:
315				q.Set(k, val)
316			case nil:
317				q.Set(k, "null")
318			default:
319				b, err := json.Marshal(val)
320				if err != nil {
321					return nil, fmt.Errorf("encode field %q: %w", k, err)
322				}
323				q.Set(k, string(b))
324			}
325		}
326		return q, nil
327	}
328	
329	// appendQuery adds encoded query params to a path that may already have some.
330	func appendQuery(path string, q url.Values) string {
331		if len(q) == 0 {
332			return path
333		}
334		sep := "?"
335		if strings.Contains(path, "?") {
336			sep = "&"
337		}
338		return path + sep + q.Encode()
339	}
340	
341	// readWithinLimit reads r up to limit bytes and errors if the source is larger,
342	// rather than silently truncating — a truncated JSON body would be malformed
343	// and misleading for an escape-hatch command.
344	func readWithinLimit(r io.Reader, limit int64) ([]byte, error) {
345		raw, err := io.ReadAll(io.LimitReader(r, limit+1))
346		if err != nil {
347			return nil, fmt.Errorf("read: %w", err)
348		}
349		if int64(len(raw)) > limit {
350			return nil, fmt.Errorf("exceeds the %d-byte limit", limit)
351		}
352		return raw, nil
353	}
354	
355	func readAPIInput(path string) ([]byte, error) {
356		if path == "-" {
357			raw, err := readWithinLimit(os.Stdin, apiMaxResponseBytes)
358			if err != nil {
359				return nil, fmt.Errorf("read body from stdin: %w", err)
360			}
361			return raw, nil
362		}
363		raw, err := os.ReadFile(path) //nolint:gosec // a user-specified request-body file is the whole point
364		if err != nil {
365			return nil, fmt.Errorf("read body file: %w", err)
366		}
367		return raw, nil
368	}
369	
370	func parseAPIHeaders(headers []string) (http.Header, error) {
371		h := make(http.Header, len(headers))
372		for _, kv := range headers {
373			k, v, ok := strings.Cut(kv, ":")
374			if !ok || strings.TrimSpace(k) == "" {
375				return nil, fmt.Errorf("invalid -H %q (want key:value)", kv)
376			}
377			h.Add(strings.TrimSpace(k), strings.TrimSpace(v))
378		}
379		return h, nil
380	}
381	
382	func writeAPIResponse(w, errW io.Writer, resp *http.Response, include bool) error {
383		if include {
384			fmt.Fprintf(errW, "%s %s\n", resp.Proto, resp.Status)
385			names := make([]string, 0, len(resp.Header))
386			for name := range resp.Header {
387				names = append(names, name)
388			}
389			sort.Strings(names)
390			for _, name := range names {
391				for _, v := range resp.Header[name] {
392					fmt.Fprintf(errW, "%s: %s\n", name, v)
393				}
394			}
395			fmt.Fprintln(errW)
396		}
397	
398		raw, err := readWithinLimit(resp.Body, apiMaxResponseBytes)
399		if err != nil {
400			return fmt.Errorf("read response body: %w", err)
401		}
402	
403		toWrite := raw
404		if body := bytes.TrimSpace(raw); len(body) > 0 && json.Valid(body) {
405			var pretty bytes.Buffer
406			if json.Indent(&pretty, body, "", "  ") == nil {
407				pretty.WriteByte('\n')
408				toWrite = pretty.Bytes()
409			}
410		}
411		if _, err := w.Write(toWrite); err != nil {
412			return fmt.Errorf("write response: %w", err)
413		}
414	
415		// Non-2xx: the body is already printed; return a silent error so the exit
416		// code is non-zero for scripts without reprinting anything.
417		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
418			return NewSilentError(fmt.Errorf("HTTP %d", resp.StatusCode))
419		}
420		return nil
421	}
