1	package auth
2	
3	import (
4		"context"
5		"encoding/base64"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"net/url"
12		"os"
13		"regexp"
14		"strings"
15		"time"
