17		"github.com/entireio/cli/cmd/entire/cli/api"
18		"github.com/entireio/cli/internal/entireclient/clusterdiscovery"
19		"github.com/entireio/cli/internal/entireclient/httputil"
20		"github.com/entireio/cli/internal/entireclient/userdirs"
21	)
22	
23	const (
24		cellDataAPITimeout = 30 * time.Second
25	
26		// JurisdictionIdentityScope is the scope jurisdiction identity tokens
27		// are minted with (also used by git-remote-entire's jurisdiction git
28		// auth). The receiving surface authorizes live per request, so the
29		// scope carries identity semantics only, not a permission grant.
30		JurisdictionIdentityScope = "openid"
31	
32		// clustersAPIPath is entire-core's cluster catalog endpoint.
33		clustersAPIPath = "/api/v1/clusters"
34	)
35	
36	// jurisdictionLabelPattern bounds a home_jurisdiction claim to a single DNS
37	// label before it is substituted into a URL template. The claim rides on the
38	// login JWT (which we decode without verifying the signature) and, for the
39	// home-jurisdiction fallback path, is attacker-influenceable if a token is ever
40	// mis-minted; constraining it to [a-z0-9-] means it can only ever name a
41	// sibling jurisdiction, never inject host/scheme syntax (e.g.
42	// "us.auth.evil.tld") into jurisdictionAudience / jurisdictionCoreURL.
43	var jurisdictionLabelPattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)
44	
45	// CellTarget pins the entire-api cell a repo-scoped call must reach and the
46	// jurisdiction its identity token must be minted for. The cli layer resolves it
47	// from the repo's own cluster (via coreapi mirrors/clusters), so a repo-scoped
48	// route reaches the cell that HOSTS the repo — not the caller's home cell. A nil
49	// target falls back to home-jurisdiction routing (derived from the login JWT),
50	// which is correct for the common same-region case and for local dev.
51	type CellTarget struct {
52		// BaseURL is the cell's apiUrl to dial (e.g. https://aws-eu-west-1.api.entire.io).
53		BaseURL string
54		// Jurisdiction is the repo's cluster jurisdiction; it drives the identity
55		// token's audience and the core the exchange is performed at.
56		Jurisdiction string
57	}
58	
59	// resolveContextForCellAPI is the discovery seam for cell routing, swapped in
60	// tests. Mirrors resolveContextForAPI.
61	var resolveContextForCellAPI resolveContextFunc = clusterdiscovery.ResolveContextForAPI
62	
63	// SetResolveContextForCellAPIForTest overrides the cell-API discovery seam.
64	func SetResolveContextForCellAPIForTest(t interface{ Helper() }, fn resolveContextFunc) func() {
65		t.Helper()
66		prev := resolveContextForCellAPI
67		resolveContextForCellAPI = fn
68		return func() { resolveContextForCellAPI = prev }
69	}
70	
71	// cellExchangeTransportForTest, when non-nil, is the HTTP transport used for
72	// jurisdiction token exchange and cluster listing. Production leaves it nil.
73	var cellExchangeTransportForTest http.RoundTripper
74	
75	// SetCellExchangeTransportForTest overrides the transport used for jurisdiction
76	// token exchange and cluster listing, returning a restore closure — the same
77	// set/restore convention the rest of the package uses for test seams.
78	func SetCellExchangeTransportForTest(t interface{ Helper() }, rt http.RoundTripper) func() {
79		t.Helper()
80		prev := cellExchangeTransportForTest
81		cellExchangeTransportForTest = rt
82		return func() { cellExchangeTransportForTest = prev }
83	}
84	
85	// NewEntireAPICellClient returns an authenticated client aimed at an entire-api
86	// cell, carrying a jurisdictional identity token (scope=openid, aud=jurisdiction
87	// host). Repo-scoped entire-api routes do not accept the narrowed api-access
88	// bearer minted for the BFF origin — they require a cell identity token
89	// (COR-666).
90	//
91	// Cell selection, in precedence order:
92	//   - target != nil: dial target.BaseURL and mint for target.Jurisdiction. This
93	//     is the repo-scoped path — the caller (cli) resolved the repo's own cell.
94	//   - the configured data host already targets a cell (host contains ".api."):
95	//     keep that origin.
96	//   - a loopback data host (local dev): keep that origin.
97	//   - otherwise the data host is a BFF/apex: resolve the caller's home-cell
98	//     apiUrl from the cluster catalog (home-jurisdiction fallback).
99	func NewEntireAPICellClient(ctx context.Context, insecureHTTP bool, target *CellTarget) (*api.Client, error) {
100		dataURL := api.BaseURL()
101		if insecureHTTP {
102			EnableInsecureHTTP()
103		} else if err := api.RequireSecureURL(dataURL); err != nil {
104			return nil, fmt.Errorf("base URL check: %w", err)
105		}
106	
107		dataOrigin := api.OriginOnly(dataURL)
108		host, ok := hostOf(dataOrigin)
109		if !ok {
110			return nil, fmt.Errorf("data API URL %q has no host to discover against", dataURL)
111		}
112	
113		dctx, cancel := context.WithTimeout(ctx, dataAPIDiscoveryTimeout)
114		defer cancel()
115		var httpClient *http.Client
116		switch {
117		case cellExchangeTransportForTest != nil:
118			httpClient = &http.Client{Timeout: cellDataAPITimeout, Transport: cellExchangeTransportForTest}
119		case shouldUsePlainHTTPDiscovery(dataOrigin):
120			httpClient = dataAPIDiscoveryClient(dataOrigin)
121			httpClient.Timeout = cellDataAPITimeout
122		default:
123			httpClient = &http.Client{Timeout: cellDataAPITimeout}
124		}
125	
126		selected, err := resolveContextForCellAPI(dctx, userdirs.Config(), userdirs.Cache(), host, httpClient, nil)
127		if errors.Is(err, clusterdiscovery.ErrDiscoveryUnavailable) {
128			return nil, fmt.Errorf("%s does not advertise its trusted login servers (/.well-known/entire-api.json missing or unreachable); cannot authenticate: %w", host, err)
129		}
130		if err != nil {
131			return nil, err
132		}
133	
134		// Gate the login provider's HTTPS relaxation on the core it actually dials
135		// (selected.CoreURL) plus the explicit --insecure-http-auth opt-in, matching
136		// the sibling ResolveDataAPIToken. A loopback data API must not relax HTTPS
137		// for a non-loopback core.
138		allowInsecure := insecureHTTPEnabled() || isLoopbackHTTP(selected.CoreURL)
139		loginProvider, err := NewRefreshingLoginProvider(selected, cellExchangeTransportForTest, allowInsecure)
140		if err != nil {
141			return nil, err
142		}
143	
144		loginJWT, err := loginProvider(ctx)
145		if err != nil {
146			if errors.Is(err, ErrNotLoggedIn) {
147				return nil, fmt.Errorf("not logged in (run 'entire login' first): %w", err)
148			}
149			// The provider already prefixes "refresh login token:"; return as-is to
150			// avoid a doubled prefix.
151			return nil, err
152		}
153	
154		jurisdiction, err := targetJurisdiction(target, loginJWT)
155		if err != nil {
156			return nil, err
157		}
158	
159		coreURL := jurisdictionCoreURL(jurisdiction, dataOrigin, selected.CoreURL)
160		if err := requireSafeExchangeURL("entire-core", coreURL); err != nil {
161			return nil, err
162		}
163	
164		cellBaseURL, err := resolveTargetCellBaseURL(ctx, target, dataOrigin, jurisdiction, coreURL, loginJWT, httpClient)
165		if err != nil {
166			return nil, err
167		}
168		if err := requireSafeExchangeURL("entire-api cell", cellBaseURL); err != nil {
169			return nil, err
170		}
171	
172		audience := jurisdictionAudience(jurisdiction, dataOrigin, selected.CoreURL)
173		token, err := exchangeJurisdictionToken(ctx, coreURL, loginJWT, audience, httpClient)
174		if err != nil {
175			return nil, fmt.Errorf("exchange jurisdictional identity token: %w", err)
176		}
177	
178		return api.NewClientWithBaseURL(token, cellBaseURL), nil
179	}
180	
181	// targetJurisdiction picks the jurisdiction to mint for: the explicit repo
182	// target when present, otherwise the caller's home jurisdiction from the login
183	// JWT. The result is validated as a DNS label before it is templated into URLs.
184	func targetJurisdiction(target *CellTarget, loginJWT string) (string, error) {
185		jurisdiction := ""
186		if target != nil {
187			jurisdiction = strings.TrimSpace(target.Jurisdiction)
188		}
189		if jurisdiction == "" {
190			var err error
191			jurisdiction, err = HomeJurisdictionFromLoginJWT(loginJWT)
192			if err != nil {
193				return "", err
194			}
195		}
196		if jurisdiction == "" {
197			return "", errors.New("login token has no home_jurisdiction claim; cannot route to entire-api cell")
198		}
199		if !jurisdictionLabelPattern.MatchString(jurisdiction) {
200			return "", fmt.Errorf("jurisdiction %q is not a valid label; refusing to route", jurisdiction)
201		}
202		return jurisdiction, nil
203	}
204	
205	// resolveTargetCellBaseURL decides which cell origin to dial. See
206	// NewEntireAPICellClient's precedence doc.
207	func resolveTargetCellBaseURL(ctx context.Context, target *CellTarget, dataOrigin, jurisdiction, coreURL, loginJWT string, httpClient *http.Client) (string, error) {
208		if target != nil && strings.TrimSpace(target.BaseURL) != "" {
209			return strings.TrimRight(target.BaseURL, "/"), nil
210		}
211		if !isBFFOrigin(dataOrigin) {
212			// Already a cell URL, or a loopback local-dev host: keep it verbatim.
213			return strings.TrimRight(dataOrigin, "/"), nil
214		}
215		return resolveCellAPIBaseURL(ctx, coreURL, loginJWT, jurisdiction, httpClient)
216	}
217	
218	// isBFFOrigin reports whether origin is a BFF / apex host that fronts multiple
219	// cells (so the actual cell must be resolved from the cluster catalog), as
220	// opposed to a direct entire-api cell (host contains ".api.") or a loopback
221	// local-dev host (kept verbatim). This is environment-agnostic: it recognises
222	// prod (entire.io), staging (partial.to) and any future apex without a
223	// hardcoded domain list.
224	func isBFFOrigin(origin string) bool {
225		u, err := url.Parse(origin)
226		if err != nil || u.Host == "" {
227			return false
228		}
229		host := strings.ToLower(u.Hostname())
230		if host == "" || isLoopbackHost(host) {
231			return false
232		}
233		// A direct cell advertises itself under an ".api." label; anything else that
234		// isn't loopback is treated as a BFF/apex needing cell resolution.
235		return !strings.Contains(host, ".api.")
236	}
237	
238	func isLoopbackHost(host string) bool {
239		switch host {
240		case "localhost", "127.0.0.1", "::1":
241			return true
242		}
243		return false
244	}
245	
246	// entireDomainFamily returns the registrable apex ("entire.io" / "partial.to")
247	// derived from the discovered login core's host, or "" for loopback/custom
248	// cores. It lets the audience/core templates follow the environment the user is
249	// actually logged into (prod vs staging) instead of a hardcoded prod default.
250	func entireDomainFamily(coreURL string) string {
251		u, err := url.Parse(coreURL)
252		if err != nil {
253			return ""
254		}
255		host := strings.ToLower(u.Hostname())
256		switch {
257		case host == "partial.to" || strings.HasSuffix(host, ".partial.to"):
258			return "partial.to"
259		case host == "entire.io" || strings.HasSuffix(host, ".entire.io"):
260			return "entire.io"
261		default:
262			return ""
263		}
264	}
265	
266	// environmentFamily picks the registrable apex to template jurisdiction URLs
267	// against. The configured data host (what the user pointed the CLI at) is the
268	// most reliable signal for prod-vs-staging, so it wins; the discovered login
269	// core is the fallback.
270	func environmentFamily(dataOrigin, discoveredCore string) string {
271		if fam := entireDomainFamily(dataOrigin); fam != "" {
272			return fam
273		}
274		return entireDomainFamily(discoveredCore)
275	}
276	
277	// jurisdictionAudience returns the aud the entire-api cell for `jurisdiction`
278	// pins its identity tokens to (its jurisdiction host). Precedence:
279	//   - ENTIRE_API_AUDIENCE_TEMPLATE (with {jurisdiction}) if set;
280	//   - else https://{jurisdiction}.<family> for the environment family;
281	//   - else (loopback/custom) the data origin, best-effort and overridable.
282	//
283	// This mirrors the BFF's buildAudience(template, jurisdiction) (repos-stream.ts).
284	func jurisdictionAudience(jurisdiction, dataOrigin, discoveredCore string) string {
285		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_API_AUDIENCE_TEMPLATE")); tmpl != "" {
286			return applyJurisdictionTemplate(tmpl, jurisdiction)
287		}
288		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
289			return "https://" + jurisdiction + "." + fam
290		}
291		return strings.TrimRight(dataOrigin, "/")
292	}
293	
294	// jurisdictionCoreURL returns the entire-core origin the identity-token exchange
295	// is performed at for `jurisdiction`. Precedence:
296	//   - a loopback discovered core (local dev): honour it verbatim — the local
297	//     core signs the local login JWT, and the prod template would send the
298	//     exchange to production, which rejects the local token;
299	//   - ENTIRE_CORE_BASE_URL_TEMPLATE (with {jurisdiction}) if set;
300	//   - else https://{jurisdiction}.auth.<family> for the environment family;
301	//   - else the discovered core verbatim.
302	//
303	// This mirrors the BFF's buildCoreBaseUrl(template, jurisdiction, fallback),
304	// which honours a fallback core when the template can't produce one.
305	func jurisdictionCoreURL(jurisdiction, dataOrigin, discoveredCore string) string {
306		if isLoopbackHTTP(discoveredCore) {
307			return strings.TrimRight(discoveredCore, "/")
308		}
309		if tmpl := strings.TrimSpace(os.Getenv("ENTIRE_CORE_BASE_URL_TEMPLATE")); tmpl != "" {
310			// Apply unconditionally: applyJurisdictionTemplate is a no-op when the
311			// template has no {jurisdiction}, yielding the fixed core verbatim — the
312			// single-core case, matching the BFF's buildCoreBaseUrl and this file's
313			// own audience handling.
314			return applyJurisdictionTemplate(tmpl, jurisdiction)
315		}
316		if fam := environmentFamily(dataOrigin, discoveredCore); fam != "" {
317			return "https://" + jurisdiction + ".auth." + fam
318		}
319		return strings.TrimRight(discoveredCore, "/")
320	}
321	
322	func applyJurisdictionTemplate(tmpl, jurisdiction string) string {
323		return strings.ReplaceAll(strings.TrimRight(tmpl, "/"), "{jurisdiction}", jurisdiction)
324	}
325	
326	// requireSafeExchangeURL rejects a target the login JWT / identity token would
327	// be sent to unless it is https (or an explicitly-allowed loopback/insecure
328	// http). It affirmatively requires the https scheme — not merely "not http" —
329	// so ftp/ws/scheme-relative/empty targets from a buggy core catalog can't
330	// smuggle the login JWT off https. Mirrors the tokenmanager guard the sibling
331	// data_api.go relies on.
332	func requireSafeExchangeURL(label, raw string) error {
333		if insecureHTTPEnabled() || isLoopbackHTTP(raw) {
334			return nil
335		}
336		u, err := url.Parse(raw)
337		if err != nil {
338			return fmt.Errorf("%s URL check: parse %q: %w", label, raw, err)
339		}
340		if u.Scheme != "https" || u.Host == "" {
341			return fmt.Errorf("%s URL %q must be https", label, raw)
342		}
343		return nil
344	}
345	
346	// HomeJurisdictionFromLoginJWT reads the home_jurisdiction claim without
347	// verifying the signature — callers only route with it; the server
348	// re-verifies. Returns "" (no error) when the claim is absent so each
349	// caller can phrase its own missing-claim error. Shared with
350	// git-remote-entire's jurisdiction git auth.
351	func HomeJurisdictionFromLoginJWT(loginJWT string) (string, error) {
352		parts := strings.Split(loginJWT, ".")
353		if len(parts) < 2 {
354			return "", errors.New("login token is not a JWT")
355		}
356		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
357		if err != nil {
358			return "", fmt.Errorf("decode login token payload: %w", err)
359		}
360		var claims struct {
361			HomeJurisdiction string `json:"home_jurisdiction"`
362		}
363		if err := json.Unmarshal(payload, &claims); err != nil {
364			return "", fmt.Errorf("parse login token payload: %w", err)
365		}
366		return claims.HomeJurisdiction, nil
367	}
368	
369	type clusterListingRow struct {
370		Jurisdiction string `json:"jurisdiction"`
371		IsDefault    bool   `json:"isDefault"`
372		APIURL       string `json:"apiUrl"`
373	}
374	
375	// resolveCellAPIBaseURL is the home-jurisdiction fallback cell resolver: it
376	// lists the caller's clusters and picks the apiUrl for `jurisdiction` (default
377	// cluster first). It hand-parses GET /api/v1/clusters rather than reusing the
378	// generated coreapi.ListClusters() because coreapi imports this (auth) package,
379	// so auth cannot import coreapi without a cycle — the repo-scoped path avoids
380	// this by resolving the cell in the cli layer (see resolveExpertsCellTarget).
381	func resolveCellAPIBaseURL(ctx context.Context, coreURL, loginJWT, jurisdiction string, httpClient *http.Client) (string, error) {
382		req, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimRight(coreURL, "/")+clustersAPIPath, nil)
383		if err != nil {
384			return "", fmt.Errorf("build clusters request: %w", err)
385		}
386		req.Header.Set("Authorization", "Bearer "+loginJWT)
387		req.Header.Set("Accept", "application/json")
388	
389		resp, err := httpClient.Do(req)
390		if err != nil {
391			return "", fmt.Errorf("list clusters: %w", err)
392		}
393		defer resp.Body.Close()
394		if resp.StatusCode != http.StatusOK {
395			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096)) //nolint:errcheck // best-effort error-detail snippet
